edits:
/* Optional left-side standings. Native disclosure works with touch and keyboard. */
.race-order{position:absolute;left:max(24px,env(safe-area-inset-left));top:132px;width:215px;max-height:calc(100dvh - 285px);overflow:auto;pointer-events:auto;background:#123946ed;color:#fff6dd;border:1px solid #c8e1d745;border-radius:12px;box-shadow:0 4px 0 #082b3433;text-shadow:none;overscroll-behavior:contain}
.race-order summary{position:sticky;top:0;background:#123946;z-index:1;cursor:pointer;padding:12px 10px;font-size:12px;font-weight:800;min-height:42px;touch-action:manipulation}
.race-order summary small{font-size:9px;color:#e0c785;margin-left:5px;font-weight:600}
.race-order summary:focus-visible{outline:3px solid #43c9ff;outline-offset:-3px}
.race-order ol{list-style:none;padding:0 6px 6px;margin:0}
.race-order li{display:grid;grid-template-columns:25px 25px minmax(0,1fr) 29px;gap:5px;align-items:center;min-height:33px;padding:3px 5px;border-top:1px solid #dbe7de12;font-size:11px;border-radius:5px}
.race-order li.is-you{background:#ffda55;color:#153b47;font-weight:800}
.order-place{font-size:11px;font-variant-numeric:tabular-nums}.order-portrait{display:grid;place-items:center;width:24px;height:24px;border:1px solid #fff4cc;border-radius:3px;overflow:hidden}.order-portrait img{width:100%;height:100%;object-fit:cover}.order-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.order-badge{font-size:7px;text-align:right;letter-spacing:.3px}
@media(max-width:640px){.race-order{left:max(12px,env(safe-area-inset-left));top:120px;width:162px;max-height:calc(100dvh - 310px)}.race-order summary{font-size:11px;padding:11px 8px}.race-order summary small{font-size:8px;margin-left:2px}.race-order li{grid-template-columns:23px 21px minmax(0,1fr) 23px;gap:3px;padding:3px;font-size:10px;min-height:29px}.order-portrait{width:20px;height:20px}.order-place{font-size:10px}.order-badge{font-size:6px}}
@media(max-height:540px) and (orientation:landscape){.race-order{top:104px;left:max(12px,env(safe-area-inset-left));width:176px;max-height:calc(100dvh - 180px)}.race-order summary{min-height:32px;padding:8px;font-size:10px}.race-order summary small{font-size:8px}.race-order li{min-height:23px;grid-template-columns:23px 19px minmax(0,1fr) 25px;gap:3px;padding:2px 3px;font-size:9px}.order-portrait{width:18px;height:18px}.order-place{font-size:9px}.order-badge{font-size:6px}}

@media(max-height:540px) and (orientation:landscape){.race-bottom{left:auto!important;right:12px;bottom:82px!important;flex-direction:column-reverse;gap:5px;align-items:end}.item-box{max-width:170px}}
